#[inline]
pub unsafe fn ZopfliLengthLimitedCodeLengths(
    mut frequencies: *const size_t,
    mut n: c_int,
    mut maxbits: c_int,
    mut bitlengths: *mut c_uint,
) -> c_int {
    // SAFETY: caller provides `frequencies` valid for `n` elements per original function contract.
    let frequencies_view: &[size_t] =
        unsafe { core::slice::from_raw_parts(frequencies, n as usize) };

    let mut pool = NodePool {
        next: ::core::ptr::null_mut::<Node>(),
    };
    let mut numsymbols: c_int = 0;
    let mut numBoundaryPMRuns: c_int;
    let mut nodes: *mut Node;
    let mut lists: *mut [*mut Node; 2];

    let leaves_size =
        (n as size_t).wrapping_mul(::core::mem::size_of::<Node>() as size_t);
    let leaves: *mut Node = malloc(leaves_size) as *mut Node;

    let n_usize = n as usize;
    let mut i = 0usize;
    while i < n_usize {
        // SAFETY: `bitlengths` is valid for `n` elements per original function contract, and `i < n`.
        unsafe { *bitlengths.add(i) = 0 as c_uint };
        i += 1;
    }

    i = 0;
    while i < n_usize {
        let freq = frequencies_view[i];
        if freq != 0 {
            // SAFETY: `leaves` points to allocation for `n` Nodes, and `numsymbols <= i < n`.
            unsafe {
                let leaf = leaves.add(numsymbols as usize);
                (*leaf).weight = freq;
                (*leaf).count = i as c_int;
            }
            numsymbols += 1;
        }
        i += 1;
    }

    if (1 as c_int) << maxbits < numsymbols {
        free(leaves as *mut c_void);
        return 1 as c_int;
    }
    if numsymbols == 0 {
        free(leaves as *mut c_void);
        return 0 as c_int;
    }
    if numsymbols == 1 {
        // SAFETY: `numsymbols == 1` means first leaf exists; stored count is original symbol index in range.
        unsafe {
            *bitlengths.add((*leaves).count as usize) = 1 as c_uint;
        }
        free(leaves as *mut c_void);
        return 0 as c_int;
    }
    if numsymbols == 2 {
        // SAFETY: `numsymbols == 2` means first two leaves exist; counts are valid original symbol indices.
        unsafe {
            let c0 = (*leaves).count as usize;
            let c1 = (*leaves.add(1)).count as usize;
            *bitlengths.add(c0) = (*bitlengths.add(c0)).wrapping_add(1);
            *bitlengths.add(c1) = (*bitlengths.add(c1)).wrapping_add(1);
        }
        free(leaves as *mut c_void);
        return 0 as c_int;
    }

    let limit = (1 as c_int as size_t)
        << (::core::mem::size_of::<size_t>() as usize)
            .wrapping_mul(CHAR_BIT as usize)
            .wrapping_sub(9usize);

    i = 0;
    let numsymbols_usize = numsymbols as usize;
    while i < numsymbols_usize {
        // SAFETY: `i < numsymbols <= n`, so this leaf is within allocation.
        unsafe {
            let leaf = leaves.add(i);
            let weight = (*leaf).weight;
            if weight >= limit {
                free(leaves as *mut c_void);
                return 1 as c_int;
            }
            (*leaf).weight = (weight << 9) | ((*leaf).count as size_t);
        }
        i += 1;
    }

    qsort(
        leaves as *mut c_void,
        numsymbols as size_t,
        ::core::mem::size_of::<Node>() as size_t,
        Some(
            LeafComparator
                as unsafe extern "C" fn(*const c_void, *const c_void) -> c_int,
        ),
    );

    i = 0;
    while i < numsymbols_usize {
        // SAFETY: `i < numsymbols <= n`, so this leaf is within allocation.
        unsafe {
            (*leaves.add(i)).weight >>= 9;
        }
        i += 1;
    }

    if numsymbols - 1 < maxbits {
        maxbits = numsymbols - 1;
    }

    let nodes_len = (maxbits * 2 * numsymbols) as size_t;
    nodes = malloc(
        nodes_len.wrapping_mul(::core::mem::size_of::<Node>() as size_t),
    ) as *mut Node;
    pool.next = nodes;

    lists = malloc(
        (maxbits as size_t)
            .wrapping_mul(::core::mem::size_of::<[*mut Node; 2]>() as size_t),
    ) as *mut [*mut Node; 2];

    InitLists(&raw mut pool, leaves, maxbits, lists);

    numBoundaryPMRuns = 2 * numsymbols - 4;
    let last = maxbits - 1;
    let mut run = 0;
    while run < (numBoundaryPMRuns - 1) as usize {
        BoundaryPM(lists, leaves, numsymbols, &raw mut pool, last);
        run += 1;
    }

    BoundaryPMFinal(lists, leaves, numsymbols, &raw mut pool, last);

    ExtractBitLengths(
        // SAFETY: `last` is in-bounds for `lists` allocation and list slot [1] exists by type.
        unsafe { (*lists.add(last as usize))[1] },
        leaves,
        bitlengths,
    );

    free(lists as *mut c_void);
    free(leaves as *mut c_void);
    free(nodes as *mut c_void);
    0 as c_int
}

